import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt
from scipy import stats
pd.set_option('display.width',250); pd.set_option('display.max_rows',200)
AA3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
 'LEU':'L','LYS':'K','MET':'M','MSE':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
def finalize(ch):
    return {c:[{'resi':int(k[0]),'icode':k[1],'resn':v['resn'],'aa':AA3.get(v['resn'],'X'),'atoms':v['atoms'],'b':v['b']}
               for k,v in sorted(d.items(),key=lambda x:(int(x[0][0]),x[0][1]))] for c,d in ch.items()}
def parse_pdb_text(txt):
    ch={}; het=[]
    for ln in txt.splitlines():
        if ln.startswith('ENDMDL'): break
        if not ln.startswith(('ATOM','HETATM')) or ln[16] not in (' ','A'): continue
        resn=ln[17:20].strip(); c=ln[21]; resi=ln[22:26].strip(); ic=ln[26]; name=ln[12:16].strip()
        xyz=np.array([float(ln[30:38]),float(ln[38:46]),float(ln[46:54])]); b=float(ln[60:66])
        if resn in AA3:
            d=ch.setdefault(c,{}).setdefault((resi,ic),{'resn':resn,'atoms':{},'b':b}); d['atoms'][name]=xyz
        elif resn not in ('HOH','DOD'): het.append((c,resn,resi,name,xyz))
    return finalize(ch),het
def parse_cif_text(txt):
    lines=txt.splitlines(); i=0
    while i<len(lines):
        if lines[i].strip()=='loop_' and lines[i+1].strip().startswith('_atom_site.'):
            cols=[]; j=i+1
            while lines[j].strip().startswith('_atom_site.'): cols.append(lines[j].strip().split('.')[1]); j+=1
            idx={c:k for k,c in enumerate(cols)}; ch={}; het=[]
            while j<len(lines) and not lines[j].strip().startswith(('loop_','#','_')):
                f=lines[j].split()
                if len(f)>=len(cols) and f[idx['pdbx_PDB_model_num']]=='1' and f[idx['label_alt_id']] in ('.','A'):
                    resn=f[idx['label_comp_id']]; c=f[idx['auth_asym_id']]; resi=f[idx['auth_seq_id']]
                    nmm=(f[idx['auth_atom_id']] if 'auth_atom_id' in idx else f[idx['label_atom_id']]).strip('"')
                    xyz=np.array([float(f[idx['Cartn_x']]),float(f[idx['Cartn_y']]),float(f[idx['Cartn_z']])])
                    b=float(f[idx['B_iso_or_equiv']]) if 'B_iso_or_equiv' in idx else 0.0
                    if resn in AA3:
                        d=ch.setdefault(c,{}).setdefault((resi,' '),{'resn':resn,'atoms':{},'b':b}); d['atoms'][nmm]=xyz
                    elif resn not in ('HOH','DOD'): het.append((c,resn,resi,nmm,xyz))
                j+=1
            return finalize(ch),het
        i+=1
def rcsb(pid):
    r=requests.get(f"https://files.rcsb.org/download/{pid}.pdb",timeout=60)
    if r.status_code==200 and not r.text.lstrip().startswith('<'): return parse_pdb_text(r.text)
    return parse_cif_text(requests.get(f"https://files.rcsb.org/download/{pid}.cif",timeout=60).text)
def kabsch(P,Q):
    pc=P.mean(0); qc=Q.mean(0); U,S,Vt=np.linalg.svd((P-pc).T@(Q-qc))
    R=Vt.T@np.diag([1,1,np.sign(np.linalg.det(Vt.T@U.T))])@U.T; return R,qc-R@pc
def nw_fast(S,g=-0.6):
    n,m=S.shape; F=np.zeros((n+1,m+1)); F[0,1:]=g*np.arange(1,m+1); F[1:,0]=g*np.arange(1,n+1); jj=np.arange(m+1)
    for i in range(1,n+1):
        G=np.empty(m+1); G[0]=-1e9; G[1:]=np.maximum(F[i-1,:-1]+S[i-1],F[i-1,1:]+g)
        b=np.empty(m+1); b[0]=F[i,0]; b[1:]=G[1:]-g*jj[1:]
        F[i]=np.maximum.accumulate(b)+g*jj
    i,j=n,m; pairs=[]
    while i>0 and j>0:
        if abs(F[i,j]-(F[i,j-1]+g))<1e-9: j-=1
        elif abs(F[i,j]-(F[i-1,j-1]+S[i-1,j-1]))<1e-9: pairs.append((i-1,j-1)); i-=1; j-=1
        else: i-=1
    return pairs[::-1]
def tmalign(Xq,Xt):
    n,m=len(Xq),len(Xt); L=min(n,m); d0=max(1.24*(L-15)**(1/3)-1.8,0.5)
    seeds=[(i,j,Ls) for Ls in [L,L//2,L//4] if Ls>=12
           for i in range(0,n-Ls+1,max(1,Ls//2)) for j in range(0,m-Ls+1,max(1,Ls//2))]
    best=(0,None,None,None)
    for si,sj,Ls in seeds:
        R,t=kabsch(Xq[si:si+Ls],Xt[sj:sj+Ls]); pairs=None
        for it in range(8):
            Xm=Xq@R.T+t; D=np.linalg.norm(Xm[:,None,:]-Xt[None,:,:],axis=2); newp=nw_fast(1/(1+(D/d0)**2))
            if pairs==newp: break
            pairs=newp; cur=np.array(pairs)
            for cut in (d0+4,d0+2,d0):
                Xm=Xq@R.T+t; dd=np.linalg.norm(Xm[cur[:,0]]-Xt[cur[:,1]],axis=1); sel=cur[dd<cut]
                if len(sel)<10: break
                R,t=kabsch(Xq[sel[:,0]],Xt[sel[:,1]])
        if not pairs: continue
        Xm=Xq@R.T+t; ix=np.array(pairs); d=np.linalg.norm(Xm[ix[:,0]]-Xt[ix[:,1]],axis=1)
        tm=float(np.sum(1/(1+(d/d0)**2))/L)
        if tm>best[0]: best=(tm,pairs,R,t)
    return best
DON={'S','T','Y','N','Q','K','R','W','H','C'}; ACC={'S','T','Y','N','Q','D','E','H'}
api=requests.get("https://alphafold.ebi.ac.uk/api/prediction/Q96MZ0",timeout=60)
print("AlphaFold API:",api.status_code)
js=api.json()[0]; print("entry:",js['uniprotAccession'],js['uniprotId'],"len",js['uniprotEnd'],"model:",js['pdbUrl'].split('/')[-1])
l1p,_=parse_pdb_text(requests.get(js['pdbUrl'],timeout=60).text)
ck=sorted(l1p)[0]; l1=[r for r in l1p[ck] if 'CA' in r['atoms'] and r['resi']<=305]
print("GDAP1L1 residues used:",len(l1),"mean pLDDT %.1f"%np.mean([r['b'] for r in l1]))
Xl=np.array([r['atoms']['CA'] for r in l1])
REFS={'1EEM':'GSTO1','6GSS':'GSTP1','2C3Q':'GSTT2','1LJR':'GSTT1'}
rows=[]; det=[]
for pid,gene in REFS.items():
    prot,het=rcsb(pid); cands={}
    for c,resn,resi,nm,xyz in het:
        if resn in ('GSH','GTX'): cands.setdefault((c,resi),[]).append((nm,xyz))
    k=max(cands,key=lambda k:len(cands[k])); LN=[n for n,_ in cands[k]]; LA=np.array([x for _,x in cands[k]])
    ref=[r for r in prot[k[0]] if 'CA' in r['atoms']]; Xr=np.array([r['atoms']['CA'] for r in ref])
    tm,pairs,R,t=tmalign(Xr,Xl); m={i:j for i,j in pairs}
    bb=sr=sl=un=0
    for ri,r in enumerate(ref):
        at={kk:v for kk,v in r['atoms'].items() if not kk.startswith('H')}
        nm=list(at); A=np.array([at[x] for x in nm]); D=np.linalg.norm(A[:,None,:]-LA[None,:,:],axis=2)
        if D.min()>4.5: continue
        qi=m.get(ri); dev=float(np.linalg.norm((Xr[ri]@R.T+t)-Xl[qi])) if qi is not None else np.nan
        ok_map = qi is not None and dev<5.0; q=l1[qi] if ok_map else None
        for a_i,an in enumerate(nm):
            if an[0] not in 'NO': continue
            for b_i,bn in enumerate(LN):
                if bn[0] not in 'NOS' or D[a_i,b_i]>3.5: continue
                if an in ('N','O','OXT'):
                    cat='backbone_retained' if ok_map else 'unmapped'; bb+=ok_map; un+=(not ok_map)
                elif not ok_map: cat='unmapped'; un+=1
                else:
                    don = an[0]=='N' or (an[0]=='O' and r['aa'] in ('S','T','Y'))
                    good=(q['aa'] in DON) if don else (q['aa'] in ACC)
                    cat='sidechain_retained' if good else 'sidechain_lost'; sr+=good; sl+=(not good)
                det.append(dict(ref=pid,gene=gene,ref_res=f"{r['aa']}{r['resi']}",atom=an,lig=bn,d=round(float(D[a_i,b_i]),2),
                                gdap1l1=(f"{q['aa']}{q['resi']}" if q else '-'),plddt=(round(q['b'],1) if q else None),cat=cat))
    rows.append(dict(ref=pid,gene=gene,TM=round(tm,3),backbone_retained=bb,sidechain_retained=sr,sidechain_lost=sl,unmapped=un))
P=pd.DataFrame(rows); P['sc_total']=P.sidechain_retained+P.sidechain_lost
P['frac_sc_lost']=(P.sidechain_lost/P.sc_total).round(3)
